if($path==='/quizzes'&&$method==='POST'){$u=user();$b=body();$specialty=filter_var($b['specialty_id']??null,FILTER_VALIDATE_INT);$topic=isset($b['topic_id'])?filter_var($b['topic_id'],FILTER_VALIDATE_INT):null;if(!$specialty||($topic!==null&&!$topic))json_response(false,'Pilihan spesialisasi atau topik tidak valid',null,422);$limit=$u['access_status']==='full'?20:5;$pdo=db();$pdo->beginTransaction();$s=$pdo->prepare("SELECT id FROM questions WHERE status='published' AND specialty_id=? AND (? IS NULL OR topic_id=?) ORDER BY RAND() LIMIT $limit");$s->execute([$specialty,$topic,$topic]);$questions=$s->fetchAll();if(!$questions){$pdo->rollBack();json_response(false,'Belum ada soal terbit untuk pilihan ini',null,422);}$pdo->prepare("INSERT INTO quiz_attempts(user_id,specialty_id,topic_id,mode,status,total_questions,duration_minutes,started_at)VALUES(?,?,?,'practice','in_progress',?,?,NOW())")->execute([$u['id'],$specialty,$topic,count($questions),count($questions)*2]);$id=$pdo->lastInsertId();$insert=$pdo->prepare('INSERT INTO quiz_attempt_questions(attempt_id,question_id,position)VALUES(?,?,?)');foreach($questions as$i=>$q)$insert->execute([$id,$q['id'],$i+1]);$pdo->commit();json_response(true,'Kuis dibuat',['id'=>(int)$id],201);}
